using System;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Windows.Forms;
namespace ShotOut {
class QuickSearchEntry {internal string Title,Detail,Text,Path,Kind,Tool;internal ClosedTabEntry Closed;internal EditorDocument Document;internal Mark Mark;}
class QuickSearchList : ListBox {
int hovered=-1;
internal QuickSearchList(){DrawMode=DrawMode.OwnerDrawFixed;ItemHeight=58;BorderStyle=BorderStyle.None;IntegralHeight=false;SetStyle(ControlStyles.OptimizedDoubleBuffer,true);BackColor=Color.FromArgb(32,32,34);ForeColor=Color.FromArgb(234,234,236);}
[System.Runtime.InteropServices.DllImport("uxtheme.dll",CharSet=System.Runtime.InteropServices.CharSet.Unicode)]static extern int SetWindowTheme(IntPtr window,string theme,string sub);
protected override void OnHandleCreated(EventArgs e){base.OnHandleCreated(e);try{SetWindowTheme(Handle,"DarkMode_Explorer",null);}catch(DllNotFoundException){}catch(EntryPointNotFoundException){}}
protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);int next=IndexFromPoint(e.Location);if(next==hovered)return;int previous=hovered;hovered=next;if(previous>=0&&previous<Items.Count)Invalidate(GetItemRectangle(previous));if(next>=0&&next<Items.Count)Invalidate(GetItemRectangle(next));}
protected override void OnMouseLeave(EventArgs e){int previous=hovered;hovered=-1;if(previous>=0&&previous<Items.Count)Invalidate(GetItemRectangle(previous));base.OnMouseLeave(e);}
protected override void OnDrawItem(DrawItemEventArgs e){if(e.Index<0||e.Index>=Items.Count)return;using(var brush=new SolidBrush(BackColor))e.Graphics.FillRectangle(brush,e.Bounds);bool selected=(e.State&DrawItemState.Selected)!=0;if(selected||e.Index==hovered)using(var path=Art.Round(new RectangleF(e.Bounds.X+5,e.Bounds.Y+3,e.Bounds.Width-10,e.Bounds.Height-6),8))using(var brush=new SolidBrush(selected?Color.FromArgb(47,47,50):Color.FromArgb(40,40,43)))e.Graphics.FillPath(brush,path);var item=(QuickSearchEntry)Items[e.Index];Glyph.Draw(e.Graphics,item.Tool??(item.Mark!=null?item.Mark.Kind:item.Kind=="Project"?"Project":"Image"),new Rectangle(e.Bounds.X+16,e.Bounds.Y+18,20,20),Color.FromArgb(166,166,174));TextRenderer.DrawText(e.Graphics,item.Title,Font,new Rectangle(e.Bounds.X+51,e.Bounds.Y+7,e.Bounds.Width-68,23),ForeColor,TextFormatFlags.EndEllipsis|TextFormatFlags.VerticalCenter|TextFormatFlags.SingleLine);TextRenderer.DrawText(e.Graphics,item.Detail,Font,new Rectangle(e.Bounds.X+51,e.Bounds.Y+30,e.Bounds.Width-68,20),Color.FromArgb(145,145,153),TextFormatFlags.EndEllipsis|TextFormatFlags.VerticalCenter|TextFormatFlags.SingleLine);}
}
class SearchFilterButton : ModernButton {
protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(Parent.BackColor);if(Selected)using(var path=Art.Round(new RectangleF(0,0,Width-1,Height-1),7))using(var brush=new SolidBrush(Color.FromArgb(49,49,53)))e.Graphics.FillPath(brush,path);TextRenderer.DrawText(e.Graphics,Text,Font,ClientRectangle,Selected?Color.FromArgb(239,239,243):Color.FromArgb(159,159,168),TextFormatFlags.VerticalCenter|TextFormatFlags.HorizontalCenter);}
}
class QuickSearchDialog : Form {
readonly TextBox query;readonly QuickSearchList results;readonly Label status,empty;readonly Timer debounce;readonly List<QuickSearchEntry> initial;List<QuickSearchEntry> files=new List<QuickSearchEntry>();readonly Action<QuickSearchEntry> selected;int generation;bool loaded;volatile bool catalogClosed;string category="All";readonly List<SearchFilterButton> filters=new List<SearchFilterButton>();readonly string[] roots,assets;
internal QuickSearchDialog(List<QuickSearchEntry> entries,string folder,RecentProject[] recent,Action<QuickSearchEntry> activate){
initial=entries;selected=activate;roots=new[]{Preferences.Current.ProjectFolder,Preferences.Current.ScreenshotFolder,folder}.Where(path=>!String.IsNullOrWhiteSpace(path)).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();assets=ProjectHistory.Current.Assets.ToArray();AutoScaleMode=AutoScaleMode.None;Text="Search ShotOut";ClientSize=new Size(760,560);StartPosition=FormStartPosition.CenterParent;FormBorderStyle=FormBorderStyle.None;ShowInTaskbar=false;Padding=new Padding(1);MaximizeBox=MinimizeBox=false;BackColor=Color.FromArgb(32,32,34);ForeColor=Color.FromArgb(235,235,240);Font=new Font("Segoe UI",14,FontStyle.Regular,GraphicsUnit.Pixel);
var top=new Panel {Dock=DockStyle.Top,Height=116,Padding=new Padding(19,15,19,8)};var row=new Panel {Dock=DockStyle.Top,Height=45,Padding=new Padding(35,9,48,0)};row.Paint+=delegate(object sender,PaintEventArgs e){Glyph.Draw(e.Graphics,"Search",new Rectangle(3,10,22,22),Color.FromArgb(167,167,176));};query=new ThemedTextBox {Dock=DockStyle.Fill,BorderStyle=BorderStyle.None,BackColor=BackColor,ForeColor=ForeColor,Font=new Font("Segoe UI",18,FontStyle.Regular,GraphicsUnit.Pixel),AccessibleName="Search tools, tabs, images and annotations"};row.Controls.Add(query);var close=new ModernButton {Text="Esc",Location=new Point(661,6),Size=new Size(39,29),AccessibleName="Close search",ForeColor=Color.FromArgb(154,154,165),BackColor=BackColor,Font=Font};close.Click+=delegate{Close();};row.Controls.Add(close);row.Resize+=delegate{close.Left=row.Width-43;};top.Controls.Add(row);
var options=new FlowLayoutPanel {Dock=DockStyle.Bottom,Height=34,WrapContents=false,Padding=Padding.Empty};foreach(string name in new[]{"All","Tools","Projects","Images","Annotations"}){string choice=name;var button=new SearchFilterButton {Text=name,Selected=name==category,Width=name=="Annotations"?110:88,Height=30,Margin=new Padding(0,0,5,0),ForeColor=ForeColor,BackColor=BackColor,Font=Font,Cursor=Cursors.Hand,AccessibleName="Search "+name.ToLowerInvariant()};button.Click+=delegate{SetCategory(choice);};filters.Add(button);options.Controls.Add(button);}top.Controls.Add(options);top.Paint+=delegate(object sender,PaintEventArgs e){using(var pen=new Pen(Color.FromArgb(53,53,58)))e.Graphics.DrawLine(pen,18,top.Height-1,top.Width-18,top.Height-1);};
var surface=new Panel {Dock=DockStyle.Fill,Padding=new Padding(10,8,10,5)};results=new QuickSearchList {Dock=DockStyle.Fill,Font=Font};empty=new Label {Dock=DockStyle.Fill,Text="No matches found. Try a different name or filter.",TextAlign=ContentAlignment.MiddleCenter,ForeColor=Color.FromArgb(150,150,160),Visible=false};surface.Controls.Add(results);surface.Controls.Add(empty);status=new Label {Dock=DockStyle.Bottom,Height=38,ForeColor=Color.FromArgb(147,147,157),Padding=new Padding(22,10,12,0)};Controls.Add(surface);Controls.Add(top);Controls.Add(status);debounce=new Timer {Interval=120};debounce.Tick+=delegate{debounce.Stop();Search();};query.TextChanged+=delegate{generation++;debounce.Stop();debounce.Start();};results.MouseDoubleClick+=delegate{ActivateResult();};Shown+=delegate{var area=Screen.FromControl(this).WorkingArea;ClientSize=new Size(Math.Min(760,area.Width-40),Math.Min(560,area.Height-80));if(Owner!=null)Location=new Point(Math.Max(area.Left+20,Math.Min(area.Right-Width-20,Owner.Left+(Owner.Width-Width)/2)),Math.Max(area.Top+20,Math.Min(area.Bottom-Height-20,Owner.Top+90)));query.Focus();SendMessage(query.Handle,0x1501,new IntPtr(1),"Search tools, tabs, images and annotations…");Search();LoadFiles(recent);};FormClosed+=delegate{catalogClosed=true;generation++;debounce.Dispose();};
}
[System.Runtime.InteropServices.DllImport("user32.dll",CharSet=System.Runtime.InteropServices.CharSet.Unicode)]static extern IntPtr SendMessage(IntPtr window,int message,IntPtr wParam,string value);
[System.Runtime.InteropServices.DllImport("dwmapi.dll")]static extern int DwmSetWindowAttribute(IntPtr window,int attribute,ref int value,int bytes);
protected override void OnHandleCreated(EventArgs e){base.OnHandleCreated(e);try{int dark=1,rounded=2;DwmSetWindowAttribute(Handle,20,ref dark,4);DwmSetWindowAttribute(Handle,33,ref rounded,4);}catch(DllNotFoundException){}catch(EntryPointNotFoundException){}}
protected override void OnSizeChanged(EventArgs e){base.OnSizeChanged(e);if(Width<2||Height<2)return;using(var path=Art.Round(new RectangleF(0,0,Width,Height),14)){var previous=Region;Region=new Region(path);if(previous!=null)previous.Dispose();}}
protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;using(var path=Art.Round(new RectangleF(.5f,.5f,Width-1,Height-1),14))using(var pen=new Pen(Color.FromArgb(62,62,68)))e.Graphics.DrawPath(pen,path);}
void LoadFiles(RecentProject[] recent){Task.Factory.StartNew(delegate{var data=new List<QuickSearchEntry>();var paths=recent.Where(item=>File.Exists(item.Path)).Select(item=>item.Path).Concat(assets.Where(File.Exists)).Concat(SavedFileCatalog.Enumerate(roots,20000,()=>catalogClosed));foreach(string path in paths.Distinct(StringComparer.OrdinalIgnoreCase)){bool project=Editor.SearchProjectPath(path);data.Add(new QuickSearchEntry {Title=System.IO.Path.GetFileName(path),Path=path,Kind=project?"Project":"Image",Detail=(project?"Saved project · ":"Saved image · ")+System.IO.Path.GetDirectoryName(path)});}Post(delegate{files=data;loaded=true;Search();});});}
void Post(Action action){if(IsDisposed||Disposing||!IsHandleCreated)return;try{BeginInvoke((Action)delegate{if(!IsDisposed&&!Disposing)action();});}catch(InvalidOperationException){}}
internal static List<QuickSearchEntry> Filter(IEnumerable<QuickSearchEntry> source,string text){var words=text.Split(new[]{' '},StringSplitOptions.RemoveEmptyEntries);return source.Where(item=>words.Length==0?item.Mark==null:words.All(word=>(item.Title??"").IndexOf(word,StringComparison.OrdinalIgnoreCase)>=0||(item.Text??"").IndexOf(word,StringComparison.OrdinalIgnoreCase)>=0||(item.Detail??"").IndexOf(word,StringComparison.OrdinalIgnoreCase)>=0)).OrderBy(item=>words.Length==0?0:item.Title.StartsWith(text,StringComparison.OrdinalIgnoreCase)?0:1).Take(80).ToList();}
internal void SetCategory(string value){category=value;foreach(var button in filters){button.Selected=button.Text==value;button.Invalidate();}Search();query.Focus();}
bool MatchesCategory(QuickSearchEntry entry){return category=="All"||category=="Tools"&&entry.Kind=="Tool"||category=="Projects"&&entry.Kind=="Project"||category=="Images"&&entry.Kind=="Image"||category=="Annotations"&&entry.Mark!=null;}
void Search(){string text=query.Text.Trim();int revision=++generation;var source=initial.Concat(files).Where(MatchesCategory).ToArray();Task.Factory.StartNew(delegate{var found=Filter(source,text);Post(delegate{if(revision!=generation)return;results.BeginUpdate();try{results.Items.Clear();results.Items.AddRange(found.ToArray());if(found.Count>0)results.SelectedIndex=0;}finally{results.EndUpdate();}empty.Visible=loaded&&found.Count==0;results.Visible=!empty.Visible;status.Text=(loaded?"":"Finding saved files · ")+"↑ ↓ Navigate     Enter Open     Esc Close";});});}
void ActivateResult(){var item=results.SelectedItem as QuickSearchEntry;if(item==null)return;Close();selected(item);}
protected override bool ProcessCmdKey(ref Message message,Keys key){if(key==Keys.Escape||key==(Keys.Control|Keys.K)){Close();return true;}if(key==Keys.Enter){ActivateResult();return true;}if(key==Keys.Down||key==Keys.Up){if(results.Items.Count>0)results.SelectedIndex=Math.Max(0,Math.Min(results.Items.Count-1,results.SelectedIndex+(key==Keys.Down?1:-1)));return true;}return base.ProcessCmdKey(ref message,key);}
internal TextBox Query {get{return query;}}internal QuickSearchList Results {get{return results;}}
}
partial class Editor {
internal static bool SearchProjectPath(string path){return IsProjectPath(path);}internal static bool SearchFileSupported(string path){return screenshotExtensions.Contains(Path.GetExtension(path).ToLowerInvariant());}
List<QuickSearchEntry> CaptureSearchEntries(){var entries=new List<QuickSearchEntry>();foreach(var pair in tools){string name=pair.Key;entries.Add(new QuickSearchEntry{Title=name=="Cut rows"?"Cut out":ToolDisplayName(name),Detail="Tool · "+KeyFor(name),Text=name=="Redact"?"blur pixelate privacy":name=="Image"?"insert picture":name=="Bucket"?"paint fill":"",Kind="Tool",Tool=name});}foreach(var closed in ClosedTabs())entries.Add(new QuickSearchEntry{Title=closed.Name,Detail="Recently closed tab · "+closed.ClosedUtc.ToLocalTime().ToString("g"),Kind="Closed",Closed=closed});for(int i=0;i<documents.Count;i++){var document=documents[i];if(document.Welcome)continue;entries.Add(new QuickSearchEntry {Title=document.Name,Detail="Open tab",Kind="Tab",Document=document});foreach(var mark in document.Marks.Where(mark=>!(mark is ImageEffectRow)).Take(5000)){string caption=String.IsNullOrWhiteSpace(mark.Name)?ToolDisplayName(mark.Kind):mark.Name;string text=mark.Text??"";if(text.Length>0)caption+=" · "+text.Substring(0,Math.Min(70,text.Length)).Replace('\n',' ');entries.Add(new QuickSearchEntry {Title=caption,Text=text,Detail="Annotation · "+document.Name+" · "+ToolDisplayName(mark.Kind),Kind="Annotation",Document=document,Mark=mark});}}return entries;}
void ShowQuickSearch(){FinishInteraction();StoreDocument();using(var search=new QuickSearchDialog(CaptureSearchEntries(),screenshotBrowsing??ScreenshotDirectory(false),ProjectHistory.Current.Items.ToArray(),entry=>Guard(delegate{OpenSearchEntry(entry);})))search.ShowDialog(this);}
void OpenSearchEntry(QuickSearchEntry entry){if(entry.Tool!=null){if(entry.Tool=="Image")InsertOptions();else ChooseTool(entry.Tool);View.Focus();return;}if(entry.Closed!=null){ReopenClosedTab(entry.Closed);return;}if(entry.Document==null){if(File.Exists(entry.Path))OpenPath(entry.Path);else UpdateStatus("This file has moved or is no longer available.");return;}int index=documents.IndexOf(entry.Document);if(index<0)return;ActivateDocument(index);if(entry.Mark==null||!Marks.Contains(entry.Mark))return;CloseImageEffects();tool="Select";Selected.Clear();Selected.Add(entry.Mark);Active=entry.Mark;SyncStyle();SyncLayers();var bounds=Active.Bounds;View.PanX=(Background.Width/2f-bounds.X-bounds.Width/2)*View.Zoom;View.PanY=(Background.Height/2f-bounds.Y-bounds.Height/2)*View.Zoom;View.Focus();View.Invalidate();}
}
}